import json
import os
import re
import subprocess

import requests
from agents import function_tool

FORECAST_SCRIPT = os.environ.get("CRM_FORECAST_SCRIPT", "scripts/forecast_pipeline.py")
SLACK_WEBHOOK_URL = os.environ.get("SLACK_FORECAST_WEBHOOK_URL", "")
_QUARTER_RE = re.compile(r"^\d{4}-Q[1-4]$")
_PIPELINE_RE = re.compile(r"^[A-Za-z0-9_\-]{1,64}$")


@function_tool
def run_pipeline_forecast_and_post(pipeline_id: str, quarter: str, channel: str, include_weighted: bool = True) -> str:
    if not pipeline_id or not _PIPELINE_RE.match(pipeline_id):
        return "Error: pipeline_id must be 1-64 letters, digits, underscores or dashes."
    if not quarter or not _QUARTER_RE.match(quarter):
        return "Error: quarter must look like '2026-Q4'."
    if not channel or not channel.startswith("#"):
        return "Error: channel must start with '#'."
    if not SLACK_WEBHOOK_URL:
        return "Error: Slack webhook is not configured."

    cmd = ["python", FORECAST_SCRIPT, "--pipeline", pipeline_id, "--quarter", quarter, "--format", "json"]
    if include_weighted:
        cmd.append("--weighted")

    try:
        proc = subprocess.run(cmd, capture_output=True, text=True, timeout=300, check=False)
    except subprocess.TimeoutExpired:
        return "Error: forecast script timed out after 300 seconds."
    if proc.returncode != 0:
        return f"Error: forecast script failed ({proc.returncode}): {proc.stderr.strip()[:500]}"

    try:
        forecast = json.loads(proc.stdout)
    except json.JSONDecodeError:
        return "Error: forecast script returned invalid JSON."

    total = forecast.get("total_pipeline", 0)
    weighted = forecast.get("weighted_total")
    deal_count = forecast.get("deal_count", 0)
    lines = [
        f"*Forecast for {pipeline_id} ({quarter})*",
        f"Open deals: {deal_count}",
        f"Total pipeline: ${total:,.2f}",
    ]
    if include_weighted and weighted is not None:
        lines.append(f"Weighted forecast: ${weighted:,.2f}")

    payload = {"channel": channel, "text": "\n".join(lines)}
    try:
        resp = requests.post(SLACK_WEBHOOK_URL, json=payload, timeout=15)
    except requests.RequestException as exc:
        return f"Forecast computed but posting to Slack failed: {exc}"
    if resp.status_code >= 300:
        return f"Forecast computed but Slack returned {resp.status_code}: {resp.text[:200]}"

    return f"Posted forecast for {pipeline_id} {quarter} to {channel}: {deal_count} deals, ${total:,.2f} total."
